from datetime import datetime, timedelta
from decimal import Decimal as D

# 1) 선언형 계약: 규칙은 데이터(사전)로 적고, 검사 코드는 하나
contract = {
    "dataset": "earnings_quarterly",
    "columns": {
        "ticker": {"required": True, "unique_with": ["fiscal_q"]},
        "revenue": {"required": True, "min": 0},
        "eps": {"required": True},
    },
    "freshness_hours": 24,
}

rows = [
    {"ticker": "005930", "fiscal_q": "2026Q3", "revenue": 86_000, "eps": 1_400},
    {"ticker": "000660", "fiscal_q": "2026Q3", "revenue": -1, "eps": 5_000},
    {"ticker": "005930", "fiscal_q": "2026Q3", "revenue": 86_000, "eps": None},
]
loaded_at = datetime(2026, 11, 22, 6, 0)
now = datetime(2026, 11, 23, 9, 0)


def check(contract, rows, loaded_at, now):
    fails = []
    seen = set()
    for i, r in enumerate(rows):
        for col, rule in contract["columns"].items():
            v = r.get(col)
            if rule.get("required") and v is None:
                fails.append(f"row{i} {col}: 비어 있음")
            if "min" in rule and v is not None and v < rule["min"]:
                fails.append(f"row{i} {col}: {v} < {rule['min']}")
            if "unique_with" in rule:
                key = (v, *[r[c] for c in rule["unique_with"]])
                if key in seen:
                    fails.append(f"row{i} {col}: 중복 {key}")
                seen.add(key)
    age = (now - loaded_at) / timedelta(hours=1)
    if age > contract["freshness_hours"]:
        fails.append(f"freshness: {age:.0f}시간 지남 (기준 {contract['freshness_hours']})")
    return fails


for f in check(contract, rows, loaded_at, now):
    print(f)

from decimal import Decimal as D

# 2) 벤더 교차 검증: 같은 종목·분기의 EPS 를 허용 오차(상대 0.5%) 안에서 비교
vendor = {("005930", "2026Q3"): D("1400"), ("000660", "2026Q3"): D("5000"), ("035420", "2026Q3"): D("2100")}
internal = {("005930", "2026Q3"): D("1400"), ("000660", "2026Q3"): D("5120"), ("035720", "2026Q3"): D("300")}
tol = D("0.005")
for k in sorted(vendor.keys() | internal.keys()):
    a, b = vendor.get(k), internal.get(k)
    if a is None or b is None:
        print(k, "한쪽에만 있음", "vendor" if a is not None else "internal")
    elif abs(a - b) / abs(a) > tol:
        print(k, f"차이 {(b - a) / a:.2%}")
